mapper.select:
SELECT
    r.reservation_id, r.user_id, r.room_id, r.check_in_date, r.check_out_date, r.guest_count,
    r.total_price, r.status, r.payment_status, r.special_requests, r.created_at, r.updated_at,
    u.username AS user_name,
    u.email AS user_email,
    u.phone AS user_phone,
    rm.name AS room_name,
    a.title AS accommodation_title,
    a.accommodation_id,
    h.business_name as host_business_name,
    DATEDIFF(r.check_out_date, r.check_in_date) AS nights
FROM reservations r
LEFT JOIN users u ON r.user_id = u.user_id
LEFT JOIN rooms rm ON r.room_id = rm.room_id
LEFT JOIN accommodations a ON r.accommodation_id = a.accommodation_id
LEFT JOIN hosts h ON a.host_id = h.host_id


        AND r.user_id = #{userId}


        AND r.room_id = #{roomId}


         AND a.accommodation_id = #{accommodationId}


        AND a.host_id = #{hostId}


        AND r.status = #{status}


        AND r.payment_status = #{paymentStatus}


        AND r.check_in_date >= #{startDate}


        AND r.check_out_date <= #{endDate}


ORDER BY r.created_at DESC

SELECT EXISTS (
    SELECT 1
    FROM reservations r
    JOIN rooms rm ON r.room_id = rm.room_id
    WHERE r.user_id = #{userId}
    AND rm.accommodation_id = #{accommodationId}
    AND r.status = 'COMPLETED'
    AND r.check_out_date < CURDATE()
)

SELECT r.reservation_id, r.user_id, rm.accommodation_id, r.room_id, r.check_in_date, r.check_out_date, r.guest_count, r.total_price, r.status, r.payment_status, r.created_at, r.updated_at, u.username AS user_name, u.email AS user_email, u.phone AS user_phone, a.title AS accommodation_title, rm.name AS room_name, h.host_id, DATEDIFF(r.check_out_date, r.check_in_date) AS nights FROM reservations r JOIN users u ON r.user_id = u.user_id JOIN rooms rm ON r.room_id = rm.room_id JOIN accommodations a ON rm.accommodation_id = a.accommodation_id JOIN hosts h ON a.host_id = h.host_id
h.host_id = #{hostId}
AND r.status = #{status}
AND r.check_in_date = #{checkInDate}
AND u.username LIKE CONCAT('%', #{guestName}, '%')
ORDER BY r.created_at DESC
ORDER BY r.check_in_date ASC
ORDER BY r.check_in_date DESC
ORDER BY r.created_at DESC
ORDER BY r.created_at DESC
LIMIT #{limit} OFFSET #{offset}

